// คืนรายชื่ออำเภอ (string[]) ของจังหวัดที่ระบุ — ใช้แทน DISTRICTS[province] แบบเดิม
export function districtsForProvince(provinceName) {
  const pIdx = PROVINCES.indexOf(provinceName);
  if (pIdx === -1) return [];
  return DISTRICTS.filter(d => d.p === pIdx).map(d => d.n);
}

// คืนรายชื่อตำบล (string[]) ของ จังหวัด+อำเภอ ที่ระบุ (เรียงตามตัวอักษร)
export function subdistrictsForDistrict(provinceName, districtName) {
  const pIdx = PROVINCES.indexOf(provinceName);
  if (pIdx === -1) return [];
  const dIdx = DISTRICTS.findIndex(d => d.p === pIdx && d.n === districtName);
  if (dIdx === -1) return [];
  return SUBDISTRICTS.filter(s => s[2] === dIdx).map(s => s[1]).sort((a, b) => a.localeCompare(b, 'th'));
}

// ค้นหาจากรหัสไปรษณีย์ 5 หลัก → คืน [{subDistrict, district, province}] (อาจมีหลายรายการ)
export function lookupByPostalCode(zip) {
  const z = Number(zip);
  if (!z) return [];
  const results = [];
  for (const [zc, name, dIdx] of SUBDISTRICTS) {
    if (zc !== z) continue;
    const d = DISTRICTS[dIdx];
    results.push({ subDistrict: name, district: d.n, province: PROVINCES[d.p] });
  }
  return results;
}

// หารหัสไปรษณีย์จาก ตำบล+อำเภอ+จังหวัด ที่เลือกแน่นอนแล้ว (ใช้ตอนเลือกตำบลเองแบบ manual ไม่ผ่าน postal lookup)
export function postalCodeForSubdistrict(provinceName, districtName, subDistrictName) {
  const pIdx = PROVINCES.indexOf(provinceName);
  if (pIdx === -1) return '';
  const dIdx = DISTRICTS.findIndex(d => d.p === pIdx && d.n === districtName);
  if (dIdx === -1) return '';
  const found = SUBDISTRICTS.find(s => s[2] === dIdx && s[1] === subDistrictName);
  return found ? String(found[0]).padStart(5, '0') : '';
}

